"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["55979"],{79439(e){e.exports=JSON.parse('{"id":"F366","slug":"reinsurance-recoveries","name":"Reinsurance: Quota Share and Excess of Loss","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Reinsurance","level":"Intermediate","aliases":["reinsurance","ceded loss","retention","layer"],"formula":{"latex":"\\\\text{Ceded}_{QS}=q\\\\,L,\\\\quad \\\\text{Recovery}_{XL}=\\\\min\\\\!\\\\left(\\\\max(L-R,0),\\\\,\\\\text{Limit}\\\\right)","also":[],"text":"Quota share: the reinsurer takes a fixed share q of every loss and premium; Excess of loss: the reinsurer pays the part of a loss above the retention R, up to the limit; Net retained loss = gross loss - recovery"},"symbols":[{"symbol":"L","meaning":"Gross loss from one event","unit":"money"},{"symbol":"q","meaning":"Quota share ceded","unit":"percent"},{"symbol":"R","meaning":"Retention: the loss the insurer keeps before the cover pays","unit":"money"},{"symbol":"Limit","meaning":"Most the excess-of-loss cover pays","unit":"money"}],"when_to_use":"Use it to see how reinsurance changes the loss an insurer keeps. A quota share reduces every loss in proportion and gives capital relief. Excess of loss protects against large single losses and leaves small ones with the insurer, and a loss beyond retention plus limit comes back to the insurer. Real programs add reinstatement premiums and exclusions.","worked_example":{"problem":"A 8.0 million loss hits an insurer. It has a 30% quota share, and separately an excess-of-loss cover paying 5.0 million above a 2.0 million retention.","inputs":{"l":8,"q":30,"r":2,"lim":5},"steps":[{"label":"Quota share recovery = q x L","working":"0.3 x 8","value":"2.40"},{"label":"Net retained, quota share only","working":"8-2.4","value":"5.60"},{"label":"Excess-of-loss recovery = min(max(L - R, 0), limit)","working":"min(max(8-2, 0), 5)","value":"5.00"},{"label":"Net retained, excess of loss only","working":"8-5","value":"3.00"},{"label":"Loss above the layer (retention + limit)","working":"max(8-2-5, 0)","value":"1.00"},{"label":"Net retained with XL first, then quota share on what remains","working":"(8-5) x (1-0.3)","value":"2.10"}],"answer":"Under the quota share the reinsurer pays 2.40 and the insurer keeps 5.60. Under the excess-of-loss cover the reinsurer pays 5.00 and the insurer keeps 3.00. The XL leaves 1.00 above the layer with the insurer. If both apply, with the quota share on the excess cover\'s retained loss, the insurer keeps 2.10."},"calculator":{"available":true,"inputs":[{"id":"l","label":"Gross loss","unit":"money","type":"number","default":8,"hint":""},{"id":"q","label":"Quota share ceded","unit":"%","type":"number","default":30,"hint":""},{"id":"r","label":"Retention","unit":"money","type":"number","default":2,"hint":""},{"id":"lim","label":"Limit of the excess layer","unit":"money","type":"number","default":5,"hint":""}],"checks":[{"expr":"l>=0 and r>=0 and lim>0","message":"Enter a non-negative loss and retention and a limit above zero."}],"steps":[{"id":"qs","label":"Quota share recovery = q x L","expr":"q*l","format":"num2"},{"id":"net1","label":"Net retained, quota share only","expr":"l-qs","format":"num2"},{"id":"xl","label":"Excess-of-loss recovery = min(max(L - R, 0), limit)","expr":"min(max(l-r, 0), lim)","format":"num2"},{"id":"net2","label":"Net retained, excess of loss only","expr":"l-xl","format":"num2"},{"id":"uncov","label":"Loss above the layer (retention + limit)","expr":"max(l-r-lim, 0)","format":"num2"},{"id":"both","label":"Net retained with XL first, then quota share on what remains","expr":"(l-xl)*(1-q)","format":"num2"}],"results":["qs","net1","xl","net2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"qs":2.4,"net1":5.6,"xl":5,"net2":3,"uncov":1,"both":2.0999999999999996}},"finder":{"finds":"What the insurer keeps after reinsurance","needs":"Loss, quota share, retention and limit"},"related":[{"slug":"insurance-float-profit","name":"Insurance Underwriting Profit and Float"},{"slug":"tranche-loss","name":"Tranche Loss Allocation (Attachment and Detachment)"},{"slug":"combined-ratio","name":"Combined Ratio (Insurers)"}],"related_ids":["F365","F316","F221"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mtext>Ceded</mtext><mrow><mi>Q</mi><mi>S</mi></mrow></msub><mo>=</mo><mi>q</mi><mtext>\u2009</mtext><mi>L</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mtext>Recovery</mtext><mrow><mi>X</mi><mi>L</mi></mrow></msub><mo>=</mo><mi>min</mi><mo>\u2061</mo><mtext>\u2009\u2063</mtext><mrow><mo fence=\\"true\\">(</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>L</mi><mo>\u2212</mo><mi>R</mi><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mtext>\u2009</mtext><mtext>Limit</mtext><mo fence=\\"true\\">)</mo></mrow></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Ceded}_{QS}=q\\\\,L,\\\\quad \\\\text{Recovery}_{XL}=\\\\min\\\\!\\\\left(\\\\max(L-R,0),\\\\,\\\\text{Limit}\\\\right)</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mtext>Ceded</mtext><mrow><mi>Q</mi><mi>S</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Ceded}_{QS}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>q</mi><mtext>\u2009</mtext><mi>L</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =q\\\\,L</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mtext>Recovery</mtext><mrow><mi>X</mi><mi>L</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Recovery}_{XL}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>min</mi><mo>\u2061</mo><mtext>\u2009\u2063</mtext><mrow><mo fence=\\"true\\">(</mo><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>L</mi><mo>\u2212</mo><mi>R</mi><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mtext>\u2009</mtext><mtext>Limit</mtext><mo fence=\\"true\\">)</mo></mrow></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\min\\\\!\\\\left(\\\\max(L-R,0),\\\\,\\\\text{Limit}\\\\right)</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"sinking-fund-payment","name":"Regular Saving Needed to Reach a Goal"},"next":{"slug":"reit-ffo-affo","name":"REIT Funds From Operations (FFO) and AFFO"},"lesson":null,"total":522}')}}]);